//! How the tower clock on the market sounds as Anselm repairs it, and the
//! first time it strikes again (`winter.rs` builds the tower and turns the
//! hands).
//!
//! At the market the clock is silent while it is stopped, ticks slowly and
//! unevenly once it is wound, and steadily once it is set right. On the
//! first market day after it runs fully, the hands sweep round to twelve,
//! the bell strikes twelve times and the first snow settles; a caption says
//! so in words (and in the log), so the moment also reads with the sound off.
//!
//! Sounds (generated by `tools/make_sounds.py`): `clock_tick_slow.ogg`,
//! `clock_tick.ogg`, `clock_strike.ogg`.

use bevy::audio::Volume;
use bevy::prelude::*;

use crate::data::{GameData, asset_exists};
use crate::day_cycle::{Phase, Progress};
use crate::harbor::Location;
use crate::i18n::Lang;
use crate::save::Settings;
use crate::ui::{GameLog, UiFont};
use crate::winter::clock_level;

/// From this share of the repairs the clock is wound and ticks slowly, and
/// from this one it is set right and ticks steadily (chapters 2 and 4 of 5).
const WOUND_FROM: f32 = 0.4;
const SET_FROM: f32 = 0.8;
/// How loud the ticking is, against the effects volume.
const TICK_VOLUME: f32 = 0.5;
const STRIKE_VOLUME: f32 = 0.9;
/// Seconds the hands take to sweep round to twelve before the bell.
pub const SWEEP_SECS: f32 = 3.0;
/// Seconds the caption stays (the strokes last about as long).
const STRIKE_SECS: f32 = 18.0;

pub struct TowerClockPlugin;

impl Plugin for TowerClockPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<ClockStrike>().add_systems(
            Update,
            (tick, begin_strike, run_strike).run_if(not(in_state(Phase::Menu))),
        );
    }
}

/// The first strike: seconds since it began, while it lasts.
#[derive(Resource, Default)]
pub struct ClockStrike(pub Option<f32>);

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Sound {
    Slow,
    Steady,
}

/// The ticking now playing.
#[derive(Component)]
struct Ticking(Sound);

#[derive(Component)]
struct Caption;

fn sound_for(level: f32) -> Option<Sound> {
    if level >= SET_FROM {
        Some(Sound::Steady)
    } else if level >= WOUND_FROM {
        Some(Sound::Slow)
    } else {
        None
    }
}

/// The clock ticks while the player is at the market by day.
fn tick(
    mut commands: Commands,
    data: Res<GameData>,
    progress: Res<Progress>,
    phase: Res<State<Phase>>,
    location: Res<Location>,
    settings: Res<Settings>,
    asset_server: Res<AssetServer>,
    playing: Query<(Entity, &Ticking)>,
) {
    let at_market = *phase.get() == Phase::Day && *location == Location::Market;
    let wanted = sound_for(clock_level(&data, &progress))
        .filter(|_| at_market && settings.sound && settings.effects > 0.0);
    let now = playing.iter().next().map(|(_, t)| t.0);
    if wanted == now {
        return;
    }
    for (e, _) in &playing {
        commands.entity(e).despawn();
    }
    let Some(sound) = wanted else {
        return;
    };
    let path = match sound {
        Sound::Slow => "sounds/clock_tick_slow.ogg",
        Sound::Steady => "sounds/clock_tick.ogg",
    };
    if !asset_exists(path) {
        return;
    }
    commands.spawn((
        Ticking(sound),
        AudioPlayer::new(asset_server.load(path)),
        PlaybackSettings {
            volume: Volume::Linear(TICK_VOLUME * settings.effects),
            ..PlaybackSettings::LOOP
        },
    ));
}

/// The first market day with the clock fully going: it strikes.
fn begin_strike(
    mut commands: Commands,
    data: Res<GameData>,
    mut progress: ResMut<Progress>,
    phase: Res<State<Phase>>,
    location: Res<Location>,
    lang: Res<Lang>,
    font: Res<UiFont>,
    mut strike: ResMut<ClockStrike>,
    mut log: ResMut<GameLog>,
) {
    let at_market = *phase.get() == Phase::Day && *location == Location::Market;
    if !at_market || progress.journal.clock_struck || clock_level(&data, &progress) < 1.0 {
        return;
    }
    // Remembered at once: the moment is not repeated after loading.
    progress.journal.clock_struck = true;
    strike.0 = Some(0.0);
    let text = lang.t("clock.first_strike");
    log.push(text.clone());
    // The caption at the bottom of the market view, clear of the tower.
    commands
        .spawn((
            Caption,
            Node {
                position_type: PositionType::Absolute,
                bottom: px(24),
                left: px(0),
                right: px(crate::ui::PANEL_WIDTH),
                justify_content: JustifyContent::Center,
                ..default()
            },
            GlobalZIndex(80),
            Pickable::IGNORE,
        ))
        .with_children(|layer| {
            layer
                .spawn((
                    Node {
                        max_width: px(620),
                        padding: UiRect::axes(px(18), px(10)),
                        border_radius: BorderRadius::all(px(6)),
                        ..default()
                    },
                    BackgroundColor(crate::ui::BG_PANEL.with_alpha(0.9)),
                    Pickable::IGNORE,
                ))
                .with_child((
                    Text::new(text),
                    crate::ui::text_font(&font.regular, 15.0),
                    TextColor(crate::ui::TEXT),
                    Pickable::IGNORE,
                ));
        });
}

/// The hands sweep (in `winter.rs`), then the bell; the caption goes when
/// the strokes have faded or the player leaves the market.
fn run_strike(
    mut commands: Commands,
    time: Res<Time<Real>>,
    phase: Res<State<Phase>>,
    settings: Res<Settings>,
    asset_server: Res<AssetServer>,
    mut strike: ResMut<ClockStrike>,
    captions: Query<Entity, With<Caption>>,
) {
    let Some(t) = strike.0 else {
        return;
    };
    let now = t + time.delta_secs();
    if t < SWEEP_SECS
        && now >= SWEEP_SECS
        && settings.sound
        && settings.effects > 0.0
        && asset_exists("sounds/clock_strike.ogg")
    {
        commands.spawn((
            AudioPlayer::new(asset_server.load("sounds/clock_strike.ogg")),
            PlaybackSettings {
                volume: Volume::Linear(STRIKE_VOLUME * settings.effects),
                ..PlaybackSettings::DESPAWN
            },
        ));
    }
    if now >= STRIKE_SECS || *phase.get() != Phase::Day {
        strike.0 = None;
        for e in &captions {
            commands.entity(e).despawn();
        }
    } else {
        strike.0 = Some(now);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_preparation_night_explains_itself() {
        let data = GameData::load();
        let lang = Lang::load("en");
        let nights: Vec<_> = data.events.iter().filter(|e| e.prepare).collect();
        assert!(
            !nights.is_empty(),
            "the first winter night teaches preparation"
        );
        for e in nights {
            let key = format!("event.{}.prepare", e.id);
            assert_ne!(lang.t(&key), key, "missing {key}");
        }
    }

    #[test]
    fn the_clock_sounds_change_with_anselm_s_repairs() {
        assert_eq!(sound_for(0.0), None);
        assert_eq!(sound_for(0.2), None);
        assert_eq!(sound_for(0.4), Some(Sound::Slow));
        assert_eq!(sound_for(0.6), Some(Sound::Slow));
        assert_eq!(sound_for(0.8), Some(Sound::Steady));
        assert_eq!(sound_for(1.0), Some(Sound::Steady));
        for path in [
            "sounds/clock_tick_slow.ogg",
            "sounds/clock_tick.ogg",
            "sounds/clock_strike.ogg",
        ] {
            assert!(asset_exists(path), "{path}");
        }
    }
}
